source("R/config.R")
source("R/helpers_smcca.R")
library(dplyr)
xlist <- readRDS(file.path(RESULT_DIR,"xlist_modal.rds")); fit <- readRDS(file.path(RESULT_DIR,"modal_smcca_fit.rds")); v <- readRDS(file.path(RESULT_DIR,"modal_canonical_variates.rds"))
pm <- calc_loadings(xlist[[1]],v$Pollution); beh <- calc_loadings(xlist[[2]],v$Behavior); brain <- calc_loadings(xlist[[3]],v$Brain)
colnames(pm)<-colnames(beh)<-colnames(brain)<-paste0("M",seq_len(N_COMPONENTS))
rownames(pm)<-PM_NAMES; rownames(beh)<-BEHAVIOR_NAMES; rownames(brain)<-paste0("Brain_",seq_len(N_BRAIN))
top20 <- bind_rows(lapply(seq_len(N_COMPONENTS),function(k){x<-top_brain_loadings(brain[,k],10);x$Mode<-paste0("M",k);x}))
write.csv(pm,file.path(RESULT_DIR,"modal_pollution_loadings.csv")); write.csv(beh,file.path(RESULT_DIR,"modal_behavior_loadings.csv")); write.csv(brain,file.path(RESULT_DIR,"modal_brain_loadings_all268.csv")); write.csv(top20,file.path(RESULT_DIR,"modal_brain_loadings_top10_pos_neg.csv"),row.names=FALSE); write.csv(pairwise_cor_table(v,N_COMPONENTS),file.path(RESULT_DIR,"modal_pairwise_canonical_correlations.csv"),row.names=FALSE)
